import{_ as e,o as i,c as s,a0 as t}from"./chunks/framework.LnjvHj4-.js";const k=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guides/installation.md","filePath":"guides/installation.md"}'),n={name:"guides/installation.md"};function l(o,a,r,h,p,d){return i(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Phenoblend is available as prepackaged installers for macOS, Windows, and Linux. Download the latest version from the <a href="https://github.com/p2gx/phenoblendtk/releases" target="_blank" rel="noreferrer">Releases</a> page.</p><h2 id="installing-on-macos" tabindex="-1">Installing on macOS <a class="header-anchor" href="#installing-on-macos" aria-label="Permalink to &quot;Installing on macOS&quot;">​</a></h2><blockquote><p><strong>File to download:</strong> <code>phenoblendtk_&lt;version&gt;_aarch64.dmg</code><br> This is the macOS installer for Apple Silicon (M1/M2/M3/M4 Macs)</p></blockquote><p>Because this application is open-source and distributed for free, it is not signed or notarized by Apple. macOS will warn you the first time you try to open it. Here&#39;s how to install:</p><ol><li>Download the <code>.dmg</code> file from the <a href="https://github.com/p2gx/phenoblendtk/releases" target="_blank" rel="noreferrer">Releases</a> page</li><li>Open the DMG and drag the app into your Applications folder</li><li>When you try to open it, macOS will show the message:<br><em>&quot;&#39;phenoblendtk&#39; is an app downloaded from the Internet. Are you sure you want to open it?&quot;</em></li></ol><p>If you confirm, the app will be installed into your `Àpplications``folder and started. From now one you can open phenoblendtk like any other application (e.g., using the Spotlight searchbar).</p><h2 id="installing-on-windows" tabindex="-1">Installing on Windows <a class="header-anchor" href="#installing-on-windows" aria-label="Permalink to &quot;Installing on Windows&quot;">​</a></h2><blockquote><p><strong>File to download:</strong> <code>phenoblendtk_&lt;version&gt;_x64_en-US.msi</code><br> Windows installer (MSI format)</p></blockquote><ol><li>Download the <code>.msi</code> installer from the <a href="https://github.com/p2gx/phenoblendtk/releases" target="_blank" rel="noreferrer">Releases</a> page</li><li>Double-click to start the installer</li><li>If Windows shows a blue SmartScreen dialog saying:<br><em>&quot;Windows protected your PC&quot;</em></li><li>Click <strong>&quot;More info&quot;</strong> → <strong>&quot;Run anyway&quot;</strong></li></ol><blockquote><p><strong>Note:</strong> Windows shows this for unsigned apps from new developers. Once you install and run it, the warning will not reappear.</p></blockquote><h2 id="installing-on-linux" tabindex="-1">Installing on Linux <a class="header-anchor" href="#installing-on-linux" aria-label="Permalink to &quot;Installing on Linux&quot;">​</a></h2><h3 id="debian-ubuntu-recommended" tabindex="-1">Debian/Ubuntu (recommended) <a class="header-anchor" href="#debian-ubuntu-recommended" aria-label="Permalink to &quot;Debian/Ubuntu (recommended)&quot;">​</a></h3><blockquote><p><strong>File to download:</strong> <code>phenoblendtk_&lt;version&gt;_amd64.deb</code><br> Debian/Ubuntu package</p></blockquote><ol><li>Download the <code>.deb</code> package from the <a href="https://github.com/p2gx/phenoblendtk/releases" target="_blank" rel="noreferrer">Releases</a> page</li><li>Install using:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./phenoblendtk_</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_amd64.deb</span></span></code></pre></div><p>Or using dpkg:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dpkg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenoblendtk_</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_amd64.deb</span></span></code></pre></div><h3 id="other-linux-distributions" tabindex="-1">Other Linux Distributions <a class="header-anchor" href="#other-linux-distributions" aria-label="Permalink to &quot;Other Linux Distributions&quot;">​</a></h3><blockquote><p><strong>File to download:</strong> <code>phenoblendtk_&lt;version&gt;_amd64.AppImage</code><br> Universal Linux application (no installation needed)</p></blockquote><ol><li>Download the <code>.AppImage</code> file from the <a href="https://github.com/p2gx/phenoblendtk/releases" target="_blank" rel="noreferrer">Releases</a> page</li><li>Make it executable:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenoblendtk_</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_amd64.AppImage</span></span></code></pre></div><ol start="3"><li>Run it:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./phenoblendtk_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;version&gt;_amd64.AppImage</span></span></code></pre></div><p><strong>Note for Arch-based distributions (e.g. EndeavourOS, Manjaro, etc.):</strong> The AppImage may not build/run correctly due to <code>linuxdeploy</code> compatibility issues. Use the <code>.deb</code> package instead (installable via <code>debtap</code>), or build from source and run the binary directly at <code>./src-tauri/target/release/phenoblendtk</code>.</p><h3 id="troubleshooting-on-linux" tabindex="-1">Troubleshooting on Linux <a class="header-anchor" href="#troubleshooting-on-linux" aria-label="Permalink to &quot;Troubleshooting on Linux&quot;">​</a></h3><h4 id="crash-on-launch-failed-to-create-gbm-buffer-hybrid-gpu-wayland" tabindex="-1">Crash on launch: <code>Failed to create GBM buffer</code> (hybrid GPU / Wayland) <a class="header-anchor" href="#crash-on-launch-failed-to-create-gbm-buffer-hybrid-gpu-wayland" aria-label="Permalink to &quot;Crash on launch: `Failed to create GBM buffer` (hybrid GPU / Wayland)&quot;">​</a></h4><p>It seems that the Tauri/wry rendering stack on Linux goes through WebKit2GTK, which by default attempts GPU-accelerated compositing via EGL and GBM. On hybrid GPU systems with NVIDIA drivers under Wayland, GBM buffer allocation can fail because the NVIDIA proprietary driver&#39;s GBM support is incomplete or incompatible with how WebKit2GTK requests buffers. The workaround is to disable WebKit2GTK GPU compositing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WEBKIT_DISABLE_COMPOSITING_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ./src-tauri/target/release/phenoblendtk</span></span></code></pre></div><h4 id="crash-during-cohort-verification-no-error-message" tabindex="-1">Crash during cohort verification (no error message) <a class="header-anchor" href="#crash-during-cohort-verification-no-error-message" aria-label="Permalink to &quot;Crash during cohort verification (no error message)&quot;">​</a></h4><p>A crash with no error message has been observed when verifying cohort data prior to Phenopacket export, after tabular data has been pasted successfully. The root cause is under investigation. If you encounter this, please report your steps in the <a href="https://github.com/P2GX/phenoblendtk/issues" target="_blank" rel="noreferrer">issue tracker</a>.</p><hr><h2 id="building-from-source" tabindex="-1">Building from Source <a class="header-anchor" href="#building-from-source" aria-label="Permalink to &quot;Building from Source&quot;">​</a></h2><p>This will work on any OS.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/P2GX/phenoblendtk.git</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenoblendtk</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>The built installers will appear under:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">src-tauri/target/release/bundle/</span></span></code></pre></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><h3 id="node-js-at-least-version-18-and-npm-at-least-version-9" tabindex="-1">Node.js (at least version 18) and npm (at least version 9). <a class="header-anchor" href="#node-js-at-least-version-18-and-npm-at-least-version-9" aria-label="Permalink to &quot;Node.js (at least version 18) and npm (at least version 9).&quot;">​</a></h3><p>You can check if you have them installed via</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p>If necessary, go to <a href="https://nodejs.org" target="_blank" rel="noreferrer">Node.js</a> to install these programs.</p><h3 id="rust-and-cargo" tabindex="-1">Rust and Cargo <a class="header-anchor" href="#rust-and-cargo" aria-label="Permalink to &quot;Rust and Cargo&quot;">​</a></h3><p>See <a href="https://rustup.rs" target="_blank" rel="noreferrer">rustup</a> if needed.</p><h3 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h3><p>If you do not have git installed, replace the cloning step with a download of the archive.</p><h2 id="platform-specific-code" tabindex="-1">Platform-specific code <a class="header-anchor" href="#platform-specific-code" aria-label="Permalink to &quot;Platform-specific code&quot;">​</a></h2><p>Please report any dependencies not listed above.</p><h1 id="running-the-app" tabindex="-1">Running the app <a class="header-anchor" href="#running-the-app" aria-label="Permalink to &quot;Running the app&quot;">​</a></h1><ol><li>Clone from GitHub</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/P2GX/phenoblendtk.git</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> phenoblendtk</span></span></code></pre></div><ol start="2"><li>Install npm dependencies From within the phenoblendtk directory, enter</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><ol start="3"><li>Running the app</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>This will run the application.</p>',56)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
